import{_ as n,W as l,s as p,u as r,ah as d,I as i,w as t,Z as s,A as a}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const D=JSON.parse('{"title":"如何分析并探索 Docker 容器镜像的内容 | LCTT x X-CMD","titleTemplate":false,"description":"如何分析并探索 Docker 容器镜像的内容 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何分析并探索 Docker 容器镜像的内容 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何分析并探索 Docker 容器镜像的内容 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181030 How To Analyze And Explore The Contents Of Docker Images","title":"如何分析并探索 Docker 容器镜像的内容","tag":"201811"},"relativePath":"201811/20181030 How To Analyze And Explore The Contents Of Docker Images.md","filePath":"[post].md"}'),c={name:"201811/20181030 How To Analyze And Explore The Contents Of Docker Images.md"};function u(g,e,m,v,h,b){const o=l("Link");return r(),p("div",null,[e[24]||(e[24]=d('<h1 id="如何分析并探索-docker-容器镜像的内容" tabindex="-1">如何分析并探索 Docker 容器镜像的内容 <a class="header-anchor" href="#如何分析并探索-docker-容器镜像的内容" aria-label="Permalink to 如何分析并探索 Docker 容器镜像的内容">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dive-tool-720x340.png" alt=""></p><p>或许你已经了解到 Docker 容器镜像是一个轻量、独立、含有运行某个应用所需全部软件的可执行包，这也是为什么容器镜像会经常被开发者用于构建和分发应用。假如你很好奇一个 Docker 镜像里面包含了什么东西，那么这篇简要的指南或许会帮助到你。今天，我们将学会使用一个名为 <strong>Dive</strong> 的工具来分析和探索 Docker 镜像每层的内容。</p><p>通过分析 Docker 镜像，我们可以发现在各个层之间可能重复的文件并通过移除它们来减小 Docker 镜像的大小。Dive 工具不仅仅是一个 Docker 镜像分析工具，它还可以帮助我们来构建镜像。Dive 是一个用 Go 编程语言编写的自由开源工具。</p><h3 id="安装-dive" tabindex="-1">安装 Dive <a class="header-anchor" href="#安装-dive" aria-label="Permalink to 安装 Dive">​</a></h3>',5)),i("p",null,[e[1]||(e[1]=t("首先从该项目的 ")),s(o,{href:"https://github.com/wagoodman/dive/releases"},{default:a(()=>e[0]||(e[0]=[t("发布页")])),_:1}),e[2]||(e[2]=t(" 下载最新版本，然后像下面展示的那样根据你所使用的发行版来安装它。"))]),e[25]||(e[25]=d('<p>假如你正在使用 <strong>Debian</strong> 或者 <strong>Ubuntu</strong>，那么可以运行下面的命令来下载并安装它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wget https://github.com/wagoodman/dive/releases/download/v0.0.8/dive_0.0.8_linux_amd64.deb</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo apt install ./dive_0.0.8_linux_amd64.deb</span></span></code></pre></div><p><strong>在 RHEL 或 CentOS 系统中</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wget https://github.com/wagoodman/dive/releases/download/v0.0.8/dive_0.0.8_linux_amd64.rpm</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo rpm -i dive_0.0.8_linux_amd64.rpm</span></span></code></pre></div>',6)),i("p",null,[e[4]||(e[4]=t("Dive 也可以使用 ")),s(o,{href:"https://www.ostechnix.com/linuxbrew-common-package-manager-linux-mac-os-x/"},{default:a(()=>e[3]||(e[3]=[t("Linuxbrew")])),_:1}),e[5]||(e[5]=t(" 包管理器来安装。"))]),e[26]||(e[26]=d('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew tap wagoodman/dive</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ brew install dive</span></span></code></pre></div>',2)),i("p",null,[e[7]||(e[7]=t("至于其他的安装方法，请参考 ")),s(o,{href:"https://github.com/wagoodman/dive"},{default:a(()=>e[6]||(e[6]=[t("Dive 项目的 GitHub 网页")])),_:1}),e[8]||(e[8]=t("。"))]),e[27]||(e[27]=d('<h3 id="分析并探索-docker-镜像的内容" tabindex="-1">分析并探索 Docker 镜像的内容 <a class="header-anchor" href="#分析并探索-docker-镜像的内容" aria-label="Permalink to 分析并探索 Docker 镜像的内容">​</a></h3><p>要分析一个 Docker 镜像，只需要运行加上 Docker 镜像 ID 的 <code>dive</code> 命令就可以了。你可以使用 <code>sudo docker images</code> 来得到 Docker 镜像的 ID。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dive ea4c82dcd15a</span></span></code></pre></div><p>上面命令中的 <code>ea4c82dcd15a</code> 是某个镜像的 ID。</p><p>然后 <code>dive</code> 命令将快速地分析给定 Docker 镜像的内容并将它在终端中展示出来。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/Dive-1.png" alt=""></p><p>正如你在上面的截图中看到的那样，在终端的左边一栏列出了给定 Docker 镜像的各个层及其详细内容，浪费的空间大小等信息。右边一栏则给出了给定 Docker 镜像每一层的内容。你可以使用 <code>Ctrl+空格</code> 来在左右栏之间切换，使用 <code>UP</code>/<code>DOWN</code> 光标键来在目录树中进行浏览。</p><p>下面是 <code>dive</code> 的快捷键列表：</p><ul><li><code>Ctrl+空格</code> —— 在左右栏之间切换</li><li><code>空格</code> —— 展开或收起目录树</li><li><code>Ctrl+A</code> —— 文件树视图：展示或隐藏增加的文件</li><li><code>Ctrl+R</code> —— 文件树视图：展示或隐藏被移除的文件</li><li><code>Ctrl+M</code> —— 文件树视图：展示或隐藏被修改的文件</li><li><code>Ctrl+U</code> —— 文件树视图：展示或隐藏未修改的文件</li><li><code>Ctrl+L</code> —— 层视图：展示当前层的变化</li><li><code>Ctrl+A</code> —— 层视图：展示总的变化</li><li><code>Ctrl+/</code> —— 筛选文件</li><li><code>Ctrl+C</code> —— 退出</li></ul><p>在上面的例子中，我使用了 <code>sudo</code> 权限，这是因为我的 Docker 镜像存储在 <code>/var/lib/docker/</code> 目录中。假如你的镜像保存在你的家目录 （<code>$HOME</code>）或者在其他不属于 <code>root</code> 用户的目录，你就没有必要使用 <code>sudo</code> 命令。</p><p>你还可以使用下面的单个命令来构建一个 Docker 镜像并立刻分析该镜像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ dive build -t &lt;some-tag&gt;</span></span></code></pre></div><p>Dive 工具仍处于 beta 阶段，所以可能会存在 bug。假如你遇到了 bug，请在该项目的 GitHub 主页上进行报告。</p><p>好了，这就是今天的全部内容。现在你知道如何使用 Dive 工具来探索和分析 Docker 容器镜像的内容以及利用它构建镜像。希望本文对你有所帮助。</p><p>更多精彩内容即将呈现，请保持关注！</p><p>干杯！</p><hr>',17)),i("p",null,[e[10]||(e[10]=t("via: ")),s(o,{href:"https://www.ostechnix.com/how-to-analyze-and-explore-the-contents-of-docker-images/"},{default:a(()=>e[9]||(e[9]=[t("https://www.ostechnix.com/how-to-analyze-and-explore-the-contents-of-docker-images/")])),_:1})]),i("p",null,[e[15]||(e[15]=t("作者：")),s(o,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>e[11]||(e[11]=[t("SK")])),_:1}),e[16]||(e[16]=t(" 选题：")),s(o,{href:"https://github.com/lujun9972"},{default:a(()=>e[12]||(e[12]=[t("lujun9972")])),_:1}),e[17]||(e[17]=t(" 译者：")),s(o,{href:"https://github.com/FSSlc"},{default:a(()=>e[13]||(e[13]=[t("FSSlc")])),_:1}),e[18]||(e[18]=t(" 校对：")),s(o,{href:"https://github.com/wxy"},{default:a(()=>e[14]||(e[14]=[t("wxy")])),_:1})]),i("p",null,[e[21]||(e[21]=t("本文由 ")),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>e[19]||(e[19]=[t("LCTT")])),_:1}),e[22]||(e[22]=t(" 原创编译，")),s(o,{href:"https://linux.cn/"},{default:a(()=>e[20]||(e[20]=[t("Linux中国")])),_:1}),e[23]||(e[23]=t(" 荣誉推出"))])])}const T=n(c,[["render",u]]);export{D as __pageData,T as default};
